"""co0112. Bank feeds, increment 1: the bank inbox (R108, design/bank-feeds.md §2, §3, §9).

Four new tables, moving no stored row: ``bank_feed_imports`` (one statement file brought into an account's inbox, never
changed), ``bank_lines`` (each line as the bank printed it, in the bank's sign, unique per account by ``line_key`` among
live lines through a partial unique index, so an overlapping download never duplicates and a reversal releases the
keys), ``bank_line_events`` (append-only history) and ``bank_feed_accounts`` (what an account last received from an OFX
file). Guards: imports and events never change; a line keeps what the bank printed, is never deleted and never comes
back to life once released. DDL below is frozen: this migration never imports current application metadata.
"""
from alembic import op

revision = 'co0112'
down_revision = 'co0111'
branch_labels = depends_on = None

DDL = ("\nCREATE TABLE bank_feed_imports (\n\tid VARCHAR(26) NOT NULL, \n\tbatch_id VARCHAR(26) NOT NULL, \n\taccount_id VARCHAR(26) NOT NULL, \n\tformat VARCHAR(8) NOT NULL, \n\tfile_sha256 VARCHAR(64) NOT NULL, \n\tattachment_id VARCHAR(26), \n\tmapping_name VARCHAR(80), \n\tdate_from VARCHAR(10), \n\tdate_to VARCHAR(10), \n\tlines_in_file INTEGER NOT NULL, \n\tlines_new INTEGER NOT NULL, \n\tcounts TEXT NOT NULL, \n\twarnings TEXT NOT NULL, \n\tmoved_from VARCHAR(26), \n\treason VARCHAR(500), \n\tcreated_by VARCHAR(26) NOT NULL, \n\tcreated_via VARCHAR(16) NOT NULL, \n\ton_behalf_of VARCHAR(26), \n\tcreated_at VARCHAR(32) NOT NULL, \n\taudit_event_id VARCHAR(26) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_bank_feed_import_format CHECK (format IN ('ofx', 'qfx', 'csv', 'feed')), \n\tCONSTRAINT ck_bank_feed_import_sha CHECK (length(file_sha256) = 64), \n\tCONSTRAINT ck_bank_feed_import_counts CHECK (lines_in_file >= 0 AND lines_new >= 0), \n\tCONSTRAINT ck_bank_feed_import_json CHECK (json_valid(counts) AND json_type(counts) = 'object' AND json_valid(warnings) AND json_type(warnings) = 'array'), \n\tFOREIGN KEY(batch_id) REFERENCES batches (id), \n\tFOREIGN KEY(account_id) REFERENCES accounts (id), \n\tFOREIGN KEY(attachment_id) REFERENCES attachments (id), \n\tFOREIGN KEY(moved_from) REFERENCES bank_feed_imports (id), \n\tFOREIGN KEY(audit_event_id) REFERENCES audit_events (id)\n)\n\n", "\nCREATE TABLE bank_lines (\n\tid VARCHAR(26) NOT NULL, \n\timport_id VARCHAR(26) NOT NULL, \n\tordinal INTEGER NOT NULL, \n\taccount_id VARCHAR(26) NOT NULL, \n\tline_key VARCHAR(120) NOT NULL, \n\tfitid VARCHAR(255), \n\tdate VARCHAR(10) NOT NULL, \n\tamount INTEGER NOT NULL, \n\tpayee TEXT NOT NULL, \n\tmemo TEXT NOT NULL, \n\tnumber VARCHAR(64) NOT NULL, \n\tkind VARCHAR(32) NOT NULL, \n\tstate VARCHAR(10) NOT NULL, \n\tlive INTEGER NOT NULL, \n\tversion INTEGER NOT NULL, \n\tentry_id VARCHAR(26), \n\tmovement TEXT, \n\tlink_how VARCHAR(8), \n\tmatch_reason VARCHAR(500), \n\tpossible_duplicate_of VARCHAR(26), \n\twarnings TEXT NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_bank_line_state CHECK (state IN ('waiting', 'matched', 'added', 'transfer', 'ignored', 'settled')), \n\tCONSTRAINT ck_bank_line_how CHECK (link_how IS NULL OR link_how IN ('auto', 'person', 'agent', 'rule')), \n\tCONSTRAINT ck_bank_line_values CHECK (live IN (0, 1) AND version >= 1 AND ordinal >= 0), \n\tCONSTRAINT ck_bank_line_amount CHECK (typeof(amount) = 'integer'), \n\tCONSTRAINT ck_bank_line_warnings CHECK (json_valid(warnings) AND json_type(warnings) = 'array'), \n\tCONSTRAINT uq_bank_line_import_ordinal UNIQUE (import_id, ordinal), \n\tFOREIGN KEY(import_id) REFERENCES bank_feed_imports (id), \n\tFOREIGN KEY(account_id) REFERENCES accounts (id), \n\tFOREIGN KEY(entry_id) REFERENCES transactions (id), \n\tFOREIGN KEY(possible_duplicate_of) REFERENCES bank_lines (id)\n)\n\n", "\nCREATE TABLE bank_line_events (\n\tid VARCHAR(26) NOT NULL, \n\tline_id VARCHAR(26) NOT NULL, \n\tkind VARCHAR(16) NOT NULL, \n\timport_id VARCHAR(26), \n\tbatch_id VARCHAR(26), \n\tdetails TEXT NOT NULL, \n\tcreated_by VARCHAR(26) NOT NULL, \n\tcreated_via VARCHAR(16) NOT NULL, \n\tcreated_at VARCHAR(32) NOT NULL, \n\taudit_event_id VARCHAR(26) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT ck_bank_line_event_kind CHECK (kind IN ('imported', 'seen_again', 'matched', 'unmatched', 'added', 'transferred', 'ignored', 'unignored', 'released', 'reversed')), \n\tCONSTRAINT ck_bank_line_event_json CHECK (json_valid(details) AND json_type(details) = 'object'), \n\tFOREIGN KEY(line_id) REFERENCES bank_lines (id), \n\tFOREIGN KEY(import_id) REFERENCES bank_feed_imports (id), \n\tFOREIGN KEY(batch_id) REFERENCES batches (id), \n\tFOREIGN KEY(audit_event_id) REFERENCES audit_events (id)\n)\n\n", "\nCREATE TABLE bank_feed_accounts (\n\taccount_id VARCHAR(26) NOT NULL, \n\tbank_number VARCHAR(64), \n\taccount_last4 VARCHAR(4), \n\tkind VARCHAR(8), \n\tlast_import_id VARCHAR(26), \n\tupdated_at VARCHAR(32) NOT NULL, \n\tversion INTEGER NOT NULL, \n\tPRIMARY KEY (account_id), \n\tCONSTRAINT ck_bank_feed_account_kind CHECK (kind IS NULL OR kind IN ('bank', 'card')), \n\tFOREIGN KEY(account_id) REFERENCES accounts (id), \n\tFOREIGN KEY(last_import_id) REFERENCES bank_feed_imports (id)\n)\n\n")
INDEXES = ('CREATE INDEX ix_bank_feed_imports_account ON bank_feed_imports (account_id, created_at)', 'CREATE INDEX ix_bank_feed_imports_file ON bank_feed_imports (account_id, file_sha256)', 'CREATE INDEX ix_bank_lines_account_state ON bank_lines (account_id, state, date)', 'CREATE INDEX ix_bank_lines_entry ON bank_lines (entry_id)', 'CREATE INDEX ix_bank_lines_fitid ON bank_lines (account_id, fitid)', 'CREATE UNIQUE INDEX uq_bank_lines_live_key ON bank_lines (account_id, line_key) WHERE live = 1', 'CREATE INDEX ix_bank_line_events_line ON bank_line_events (line_id)')
GUARDS = ("CREATE TRIGGER bank_feed_imports_no_update BEFORE UPDATE ON bank_feed_imports BEGIN SELECT RAISE(ABORT, 'bank feed imports are never changed'); END", "CREATE TRIGGER bank_feed_imports_no_delete BEFORE DELETE ON bank_feed_imports BEGIN SELECT RAISE(ABORT, 'bank feed imports are never deleted'); END", "CREATE TRIGGER bank_lines_fixed_update BEFORE UPDATE ON bank_lines WHEN NEW.id IS NOT OLD.id OR NEW.import_id IS NOT OLD.import_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.account_id IS NOT OLD.account_id OR NEW.line_key IS NOT OLD.line_key OR NEW.fitid IS NOT OLD.fitid OR NEW.date IS NOT OLD.date OR NEW.amount IS NOT OLD.amount OR NEW.payee IS NOT OLD.payee OR NEW.memo IS NOT OLD.memo OR NEW.number IS NOT OLD.number OR NEW.kind IS NOT OLD.kind OR (OLD.live = 0 AND NEW.live = 1) BEGIN SELECT RAISE(ABORT, 'a bank line keeps what the bank printed'); END", "CREATE TRIGGER bank_lines_no_delete BEFORE DELETE ON bank_lines BEGIN SELECT RAISE(ABORT, 'bank lines are never deleted'); END", "CREATE TRIGGER bank_line_events_no_update BEFORE UPDATE ON bank_line_events BEGIN SELECT RAISE(ABORT, 'bank line events are append-only'); END", "CREATE TRIGGER bank_line_events_no_delete BEFORE DELETE ON bank_line_events BEGIN SELECT RAISE(ABORT, 'bank line events are append-only'); END", "CREATE TRIGGER bank_feed_accounts_no_delete BEFORE DELETE ON bank_feed_accounts BEGIN SELECT RAISE(ABORT, 'bank feed accounts are never deleted'); END")
TABLES = ('bank_feed_accounts', 'bank_line_events', 'bank_lines', 'bank_feed_imports')
# What a test rewinding a head file drops: the guards, then the tables (children first).
TRIGGERS = tuple(statement.split()[2] for statement in GUARDS)


def upgrade():
    connection = op.get_bind()
    reserved = set(TABLES) | set(TRIGGERS) | {statement.split(' ON ')[0].split()[-1] for statement in INDEXES}
    existing = {name.casefold() for name in connection.exec_driver_sql('SELECT name FROM sqlite_schema').scalars().all()}
    if {name.casefold() for name in reserved} & existing:
        raise RuntimeError('co0112 reserved object already exists')
    for statement in DDL + INDEXES + GUARDS:
        connection.exec_driver_sql(statement)


def downgrade():
    raise RuntimeError('Company migrations are forward-only')
